    {
      "type": "entity",
      "quote": "Sezione affari del Consiglio federale",
      "gist": "Section for Affairs of the Federal Council"
    },
    {
      "type": "claim",
      "quote": "verifica che i dossier annunciati dai dipartimenti e dalla CaF siano completi e controlla che vengano trasmessi entro i termini previsti",
      "gist": "Verifies completeness of dossiers and timely submission"
    },
    {
      "type": "number",
      "quote": "Quattro giorni",
      "gist": "Four days before the meeting"
    },
    {
      "type": "claim",
      "quote": "prepara l’ordine del giorno",
      "gist": "Prepares the agenda"
    },
    {
      "type": "condition",
      "quote": "Non appena un dipartimento o la CaF trasmette una proposta concernente un affare",
      "gist": "As soon as a department or CaF submits a proposal for a case"
    },
    {
      "type": "claim",
      "quote": "la Sezione avvia la procedura di corapporto inoltrando la proposta agli altri dipartimenti e alla CaF",
      "gist": "The Section initiates the co-reporting procedure by forwarding the proposal to other departments and CaF"
    }
  ]
